var e={"29268u":`RoboKit — zbuduj i zasymuluj robota-auto`,qvztjl:`RoboKit — początek samouczka`,s42iv2:`academe.com.br (otwiera się w nowej karcie)`,"16us7mj":`Język`,ktdb8o:`Ustawienia`,"198kuu7":`Warsztat 3D`,ia581p:`Animacja`,j4z771:`Pauza`,wlqobg:`Pauza (spacja)`,h23ysv:`Szybkość odtwarzania`,r953rm:`Powiększenie`,"19blqjd":`Powiększ`,"110wpq2":`Pomniejsz`,q5w460:`Widok`,bldqt5:`Widok rozstrzelony (E)`,"44cnpg":`Widok pościgowy: jedź za autem od tyłu (C)`,"13epjbk":`Mapa areny testowej z góry`,j4zjee:`Wybrana przeszkoda`,yq1vr3:`Środka przeszkody, liczone od środka areny, gdzie auto startuje przodem do góry mapy`,"19kd62s":`Dostosuj arenę`,l1a70i:`Dostosuj arenę: przesuwaj, obracaj i zmieniaj rozmiar przeszkód`,"15n0apn":`Cofnij ostatnią zmianę (Ctrl+Z). Ctrl+Shift+Z ją przywraca`,j4uzpn:`Arena w pierwotnym stanie, z autem z powrotem na starcie`,"84sbk0":`Zostaw arenę taką, jaka była (Esc)`,"1oy9vz":`Użyj tej areny: widok 3D zostanie przebudowany, a symulacja trwa dalej`,ium5z9:`Jak program auta podejmuje decyzje`,vq0gg8:`Zamknij schemat blokowy`,s2tc63:`Zamknij (Esc)`,"13bjj4d":`Przełącz auto na Auto i patrz, jak decyduje`,gfubiu:`Jak program podejmuje decyzje: otwórz schemat blokowy`,"1gh0at8":`Kroki samouczka`,"61nq88":`Wcześniejsze kroki`,ga5x9q:`Późniejsze kroki`,"1v1ybkn":`Jazda`,"9anomo":`Do przodu (W / ↑)`,bbake2:`Skręć w lewo (A / ←)`,bfl95g:`Stop (spacja)`,iseiwq:`Skręć w prawo (D / →)`,"4o292l":`Do tyłu (S / ↓)`,"10qzszt":`Prędkość silników`,"2yhdcy":`Tryb jazdy`,"8m10x9":`Ręczny (1)`,"1ogxhr7":`Omijanie przeszkód (2)`,"1i3ygcv":`Wyłącz silniki (3)`,"1dlx0na":`Brzęczyk (B)`,isqcd9:`Kąt serwa`,"29ulgm":`Wyjście szeregowe`,"1l0xxoj":`Zamknij`,"2r1h4p":`Połączenie`,cwepyb:`Ładowanie…`,"10iu545":`RoboKit do działania potrzebuje JavaScriptu.`,"120y7gz":`Zaprojektował`,"1hpelzf":`Płytka`,"1j2fqe6":`WARSZTAT`,"17d8vhd":`Krok 1 · Zbierz części`,gqo5v1:`Symulator`,"1py6ulk":`Kliknij, aby obejrzeć`,"1ms3o1u":`Odległość`,"2w2xwg":`Prędkość`,n44ilu:`Tryb`,"1d2vfr6":`Serwo`,"152va0w":`Symulacja wstrzymana`,"11i7yk1":`Kliknij przeszkodę, aby ją zaznaczyć.`,"1a4x3zw":`Rozmiar`,"1kpdcfp":`Długość`,gfxz9b:`Szerokość`,s3robe:`Średnica`,"7puwki":`Wysokość`,kbxnhn:`Obrót`,"7nkn2r":`Położenie, od startu`,v1hcj2:`Naprzód`,"1vf2pel":`W prawo`,"1xakelj":`Shift`,"1esrfu8":`kroki po 5 cm, 15°`,yvgdmk:`Alt`,"1w55ans":`rozmiar od środka`,"1xzs12p":`przesuń ·`,"14bbmnu":`obróć`,g7xa5b:`Arena · 3 × 3 m`,vmlwpb:`Cofnij`,"2zps2o":`Przywróć`,ew9em3:`Anuluj`,lewgh4:`Zapisz`,"1vz8dhj":`Jak program podejmuje decyzje`,m76rx7:`Wybierz blok, aby zobaczyć jego kod`,"1hnif0x":`Przebieg programu`,"11rknnz":`Na żywo`,"540b06":`Auto`,"1fr6xqr":`Zbierz części`,"1wu7r43":`Ręczny`,ky4lc5:`Stop`,"152av8f":`Elementy wykonawcze`,"1df7dln":`Brzęczyk`,pksfl2:`jazda ·`,"1hrh82t":`Spacja`,"9zyeew":`stop ·`,jw8yab:`tryb ·`,j4ckle:`brzęczyk ·`,kzo6rh:`pościg`,mcpijf:`Monitor portu szeregowego`,"1aeugy":`Wyczyść`,"1jgmzoq":`← Wstecz`,c9ljxw:`kroki`,"1padbm0":`Dalej`,g6g542:`Wróć do kroku`,"1k7z1pa":`Esc`,dpexcn:`Dane`,"8f4gnm":`Przejdź do kroku`,qy3p54:`USTAWIENIA`,"12znfuf":`Krok jazdy łączy się z`,"17rhf7d":`Prawdziwe auto (Wi-Fi ESP32)`,dsq8ip:`Adres auta`,"1ihj7t4":`Obraz i dźwięk`,oh792y:`Odtwarzaj brzęczyk przez głośniki`,"1bxmuya":`Pokaż wiązkę ultradźwiękową`,"1gxdv01":`Kamera podąża za autem`,"9mmtn3":`Zresetuj symulację`,"1k6e5zv":`Zastosuj`,"1iptqu5":`Nieprawidłowy URL „{url}”`,"12bfr2h":`URL musi zaczynać się od ws:// lub wss://`,"1s22nop":`Łączenie z {url}`,"1q17yrm":`Ponowna próba za {s} s`,hsi0bv:`Brak danych z auta`,ye8ewg:`Połączono`,"1puhp9v":`Łączenie…`,y1y3f2:`Brak danych`,ci4tze:`Rozłączono`,"1fmx9lv":`Błąd połączenia`,"19wtqq3":`Połączono · {board}`,"1b4ym3j":`Wbudowany symulator`,bgnl0z:`Rozgrzewanie grafiki`,"39rjx0":`Gotowe`,"1ruee97":`Warsztat 3D nie mógł się uruchomić. Potrzebuje WebGL: spróbuj innej przeglądarki albo włącz akcelerację sprzętową.`,xa5swu:`ARENA TESTOWA`,"18xfupg":`Steruj przyciskami po prawej`,khccvm:`Steruj klawiszami W A S D lub przyciskami po prawej`,vhwww6:`Krok {n} · {title}`,"1i98668":`Budowanie auta`,y9b5jm:`Rozkładanie części`,qzfxj5:`Pokaż linię {n} na warsztacie`,pj86x7:`Pokaż to na warsztacie`,"13bzcw5":`Skopiowano`,"8gdme8":`Zaznacz i skopiuj`,s6g5lw:`Kopiuj`,"1bstp0v":`Lista materiałów`,"1g4j0cl":`Będziesz potrzebować`,"15cdqf0":`Narzędzia`,"1wrxvmg":`Zrób to`,"1x0ptmh":`Mapa pinów · {board}`,"1go9otx":`Szkice`,zvnhd5:`Szkic`,t8quxl:`Pobierz`,na9qmv:`Jeśli coś nie działa`,"5mau71":`Uwaga`,"1xh5jos":`{kicker} · Krok {n} z {total}`,slbawy:`Dalej: {step} →`,"7rhhil":`Od początku ↺`,"1mtyvb1":`Krok {n}: {step} · odhaczono {done} / {total}`,"4x1xaj":`Krok {n}: {step}`,d2gue0:`Karton`,"1xebpbq":`Drewniany klocek`,hi63vm:`Puszka`,"14yz9o9":`Doniczka`,"1g6nbya":`Musi zostać wewnątrz ścian.`,v23nvk:`Miejsce startu auta musi pozostać wolne.`,"1d1sqge":`Tam stoi auto.`,sjcnug:`Dwie przeszkody nie mogą być w tym samym miejscu.`,"1rjq9tt":`Przeciągnij przeszkodę, aby ją przesunąć. Kwadratowe uchwyty zmieniają jej rozmiar, okrągły ją obraca.`,qaws2z:`Arena z góry. Kliknij przeszkodę, aby ją zaznaczyć, przeciągnij, aby ją przesunąć. Z klawiatury: Page Down i Page Up wybierają przeszkodę, strzałki ją przesuwają, R ją obraca.`,km6rtw:`Przeszkoda`,v6zgjh:`Arena w pierwotnym stanie. Zapisanie odstawia auto na start.`,"1bneya5":`Każda runda zaczyna się tutaj`,"1gvmqkj":`Decyzja`,"2wk0tb":`Działanie`,ltbyq8:`tak`,r90oai:`nie`,"10pfeta":`{file} · linie {lines}`,"1mv69ab":`{file} · linia {lines}`,v5glvz:`brak echa`,"1y6bn7c":`lewo {left} · prawo {right}`,"17yvayv":`Droga wolna: jedzie dalej`,g8loky:`{reading} przed nim · staje poniżej {stop} cm`,"1qpxp29":`Stop · LED włączona · pisk`,lman68:`przeszkoda w odległości {reading} · poniżej {stop} cm`,"4e4gg4":`Wycofał się: rozgląda się`,"1x1kke3":`odczyt nie zmienił się przez {s} s`,"1pc4lzp":`Cofnął się: patrzy ponownie`,"11qad25":`po obu stronach było za ciasno na skręt`,dfsfd7:`Utknął: wycofuje się`,eic5lt:`odczyt bez zmian przez {s} s`,n7w5mt:`Brak miejsca na skręt: cofa się`,etina8:`{sides} · poniżej {tight} cm`,crgp5w:`Patrzy w prawo`,vto9jk:`odczyt {reading}`,"1xubspn":`Patrzy w lewo`,"92dcjq":`prawo {right} · lewo odczyt {reading}`,cfs13v:`Jest miejsce na skręt?`,h7zzeh:`{sides} · potrzeba {tight} cm`,qlw2zr:`Znowu skręca w lewo`,"1fd6gkc":`Znowu skręca w prawo`,"1hj21ci":`zablokowany zaraz po skręcie: w tę samą stronę`,"1jk1kpr":`Skręca w lewo`,u6ps9c:`Skręca w prawo`,"1uvg70v":`Auto jest wyłączone`,"1bbdvwo":`Widok na żywo: tylko symulowane auto`,"1fj8dwo":`przełącz na Auto, aby patrzeć, jak auto decyduje`,"14g7i3l":`prawdziwe auto przesyła odczyty, a nie krok swojej procedury`,"15nlm70":`Wróć do kroku {n} · {step}`,"1i8tm8j":`Montowane w <b>tym kroku</b>`,rpu2qi:`Montowane w <b>kroku {n} · {step}</b>`,"1b4o3fw":`Przejdź do kroku {n} →`,y322vs:`Język: {name}`,bk85tv:`Odtwórz`,"1x4eyna":`{action} (spacja)`,gpdo6z:`Użyj adresu ws:// lub wss://, np. ws://192.168.4.1:81/`,"1iquufv":`Najpierw połącz się z siecią Wi-Fi auta. W README.md opisano format wiadomości, którym musi mówić firmware.`,njqkz2:`Wpisz URL WebSocket, np. ws://192.168.4.1:81/`,nrzvmi:`Jeździ symulowanym autem po arenie testowej — bez sprzętu.`,cegybp:`Części`,wv4sck:`Przygotowanie`,"7z3mbb":`Wszystko do czterokołowego łazika z ultradźwiękową „głową”, która potrafi się rozglądać. Rozłóż części w ten sposób i odhaczaj je po kolei. Najedź na wiersz, aby znaleźć część na macie, albo kliknij część, aby zobaczyć szczegóły.`,"1x97es5":`Przed rozpoczęciem naładuj ogniwa 18650 w porządnej ładowarce Li-ion i używaj ogniw z zabezpieczeniem: ogniwo bez zabezpieczenia może dać dziesiątki amperów w zwarcie.`,"13wu8qd":`Akrylowe podwozie — dolna, środkowa i górna płyta`,"9z9vwl":`Silniki TT z przekładnią (3–6 V, 1:48) z 8 akrylowymi uchwytami w kształcie litery T, 8 śrubami M3 × 30 i nakrętkami`,"1qr4ely":`Koła, 65 mm`,cmzolq:`Moduł podwójnego sterownika silników L9110S`,"1qgfn27":`Arduino UNO R3 + Sensor Shield V5 + kabel USB`,"15cdntm":`ESP32 DevKit V1 (30 pinów) + płytka rozszerzeń + kabel USB`,mfnvxi:`Czujnik ultradźwiękowy HC-SR04 + jego uchwyt do serwa i wkręty`,"15iavp3":`Mikroserwo SG90 z orczykami i wkrętami`,"1allzrf":`Ogniwa Li-ion 18650 (z zabezpieczeniem) + koszyk na 2 ogniwa szeregowo z przewodami`,xooybo:`Przełącznik suwakowy, czerwona dioda LED 10 mm, rezystor 220 Ω, brzęczyk aktywny 5 V`,"1csc29i":`Przełącznik suwakowy, czerwona dioda LED 10 mm, brzęczyk aktywny 5 V, tranzystor NPN (PN2222A lub S8050), rezystory 220 Ω, 2 × 1 kΩ i 2 kΩ`,"17dpcif":`Wtyk DC z zaciskami śrubowymi, 5.5 × 2.1 mm`,bozwcy:`20 przewodów połączeniowych żeńsko-żeńskich, 15 cm; czerwony i czarny przewód montażowy; 16 mosiężnych tulejek dystansowych M3 z gwintem wewnętrznym po obu stronach (8 × 25 mm, 4 × 15 mm, 4 × 10 mm), 32 wkręty M3 × 6 mm, taśma piankowa, rurka termokurczliwa`,"5z6ae7":`Lutownica, cyna`,"1xhh6dp":`przewody silników, włącznik, przewody LED i brzęczyka`,"11dguvz":`Małe śrubokręty`,"1b1pnob":`krzyżakowy do wkrętów M3, płaski do zacisków sterownika i wtyku`,"1ligzav":`Szczypce tnące / ściągacz izolacji`,"3pb5yx":`cięcie i zdejmowanie izolacji z przewodu montażowego i przewodów połączeniowych`,"1avt53n":`Multimetr`,"1slxnnr":`sprawdzenie biegunowości przed podaniem zasilania`,"100w2b7":`Ładowarka Li-ion`,"64j96q":`do ogniw 18650`,"1heknmc":`Komputer, Arduino IDE`,"1mo2nzj":`do wgrania kodu w kroku 9`,t9gk37:`Silniki`,"15i6udf":`Budowa`,"1fofbt3":`Silniki i koła`,"15llile":`Każdy silnik TT to mały silnik DC napędzający plastikową przekładnię 1:48. Dwa lewe i dwa prawe silniki zawsze kręcą się razem, jak gąsienice czołgu: auto skręca, gdy obie strony jadą z różną prędkością.`,k5fimq:`Czerwony na wewnętrznej blaszce każdego silnika pozwala w kroku 4 łączyć czerwony z czerwonym: przedni i tylny silnik jednej strony są zwrócone do siebie, więc ich wewnętrzne blaszki pełnią tę samą funkcję. Blaszki są cienkie i odłamują się, gdy szarpnie się przewód, więc przyklej taśmą każdą parę przewodów do jej silnika. Przewody sterczą na środku, żeby długa szczelina środkowej płyty mogła na nie opaść w kroku 3.`,"7fte4n":`Dolna płyta`,rbcm1a:`Silniki TT z przekładnią`,sjfn38:`Akrylowe uchwyty silników w kształcie litery T`,"732lu":`Śruby M3 × 30 i nakrętki`,skq14t:`Koła`,"1s4rmq":`Postaw cztery silniki na ich miejscach na dolnej płycie, wałkami na zewnątrz, końcami silników do środka. Przylutuj do każdego dwa przewody o długości około 15 cm: czerwony do blaszki bliżej środka auta, czarny do blaszki bliżej koła. Postaw osiem przewodów razem na środku płyty.`,"1mrwedd":`Podnieś płytę. Od spodu wsuń uchwyt przez szczelinę po wewnętrznej stronie każdego silnika, a drugi w wycięcie w krawędzi płyty po zewnętrznej stronie. Przełóż dwie śruby M3 × 30 przez uchwyt, przekładnię i uchwyt, łbami od strony koła, i dokręć na każdej nakrętkę.`,"13sq8kw":`Nasuń koło na każdy wałek. Wałek ma dwa spłaszczenia, które pasują do piasty, więc koło nie może się na nim obracać.`,"199dyzl":`Płyty`,qr73r6:`Złóż płyty`,kig8cy:`Mosiężne tulejki dystansowe unoszą środkową płytę 25 mm nad dolną, ponad przekładnie silników o wysokości 22 mm, i dają elektronice płaską podłogę. Każda tulejka ma gwint na obu końcach: jeden wkręt wchodzi od dołu przez płytę pod nią, drugi od góry przez to, co na niej leży.`,"1w8a39y":`Akryl pęka przy zbyt mocnym dokręceniu, więc wystarczy dokręcić z wyczuciem. Podwozia się różnią: jeśli twoje nie ma otworu tam, gdzie potrzebuje go kontroler, dwie tulejki i kawałek taśmy piankowej pod drugim końcem mocno utrzymają płytkę.`,jcqip:`Środkowa płyta`,u6l9bq:`Mosiężne tulejki dystansowe M3 × 25 mm`,"4cdagt":`Mosiężne tulejki dystansowe M3 × 10 mm (pod kontroler)`,xaqs1y:`Mosiężne tulejki dystansowe M3 × 15 mm (pod górną płytę)`,"300byl":`Wkręty M3 × 6 mm`,tezznv:`Przykręć osiem tulejek 25 mm do dolnej płyty, po cztery wzdłuż każdego boku, każdą na wkręt włożony od spodu.`,"70hnlv":`Zanim założysz środkową płytę, póki da się jeszcze sięgnąć pod nią, przymocuj cztery tulejki 10 mm pod otworami montażowymi kontrolera (przyłóż płytkę, aby zobaczyć, które otwory płyty pasują) i cztery tulejki 15 mm w rogach jej tylnej połowy, każdą wkrętem od spodu.`,"1tynoxv":`Opuść środkową płytę na tulejki 25 mm, przeciągając przy tym przewody silników w górę przez długą szczelinę na jej środku, i przykręć ją.`,"1n5adbz":`Sterownik`,"1ri406w":`Zamontuj sterownik silników`,"5n5nar":`Pin mikrokontrolera nie powinien dawać więcej niż około 20 mA, a silnik TT pobiera podczas jazdy kilkaset mA, a zablokowany ponad 1 A. Moduł L9110S ma dwa mostki H, które przełączają prąd z baterii przez silniki i potrafią go odwrócić.`,"1uicxnj":`Która śruba zacisku dostanie którą parę, na razie nie ma znaczenia: test okablowania w kroku 9 pokaże, czy któraś strona kręci się do tyłu albo czy któreś koło kręci się przeciw swojemu partnerowi. Zostaw wolne 6-pinowe złącze (B-IA, B-IB, GND, VCC, A-IA, A-IB): zasilanie dojdzie w kroku 7, a sygnały w kroku 8. L9110S wytrzymuje 800 mA na kanał, a każdy kanał napędza tu dwa silniki: wystarczy do normalnej jazdy, ale nie trzymaj kół zablokowanych. Jeśli układy się grzeją, moduł TB6612FNG (1.2 A na kanał) jest solidniejszym zamiennikiem.`,utkklb:`Kawałek dwustronnej taśmy piankowej`,syij08:`Przyklej sterownik taśmą piankową do środkowej płyty, przed tulejkami kontrolera i na lewo od środka: 6-pinowym złączem do lewej krawędzi auta, zaciskami śrubowymi do środka auta.`,"15kkcap":`Zegnij przewody do przodu wzdłuż płyty i doprowadź je do zacisków sterownika. Skręć razem dwa czerwone przewody lewych silników i razem ich dwa czarne, i przykręć obie pary w MOTOR-A, zacisku bliżej kontrolera. Zrób to samo z przewodami prawych silników w MOTOR-B.`,"18rvg69":`Kontroler`,ync8b9:`Zamontuj Arduino UNO`,"1u68uls":`Zamontuj ESP32`,ertyxs:`Arduino UNO (ATmega328P, 16 MHz, logika 5 V) uruchamia twój szkic. Na wierzch wpina się Sensor Shield V5, który daje każdemu pinowi własne złącze G / V / S (masa, 5 V i sygnał), bo złącze zasilania UNO ma tylko jeden pin 5 V do podziału między serwo i czujnik.`,"1p7bu2t":`ESP32 (dwurdzeniowy, do 240 MHz, Wi-Fi i Bluetooth, logika 3.3 V) uruchamia twój szkic i pozwala RoboKit sterować prawdziwym autem przez Wi-Fi. Jego płytka rozszerzeń dodaje gniazdo DC ze stabilizatorem i złącze G / V / S dla każdego pinu.`,ii2aq7:`Piny UNO pracują na 5 V, więc czujnik i serwo podłącza się prosto do shielda.`,"1ghuj2z":`Piny ESP32 pracują na 3.3 V i nie znoszą 5 V, więc wyjście Echo czujnika dostanie w kroku 8 dzielnik napięcia.`,t5ws5g:`ESP32 DevKit V1 (30 pinów)`,"1tu8qz5":`Płytka rozszerzeń ESP32 (30 pinów)`,"14w4gx0":`Przykręć UNO na czterech tulejkach 10 mm za sterownikiem silników, gniazdami USB i DC do lewej strony auta.`,hw767j:`Wciśnij Sensor Shield V5 na UNO, każdy pin w swoje gniazdo. Zostaw założoną zworkę SEL, aby piny V shielda brały 5 V z UNO, i nie podłączaj niczego do zacisku śrubowego shielda.`,"1opbgrl":`Przykręć płytkę rozszerzeń na czterech tulejkach 10 mm za sterownikiem silników, gniazdem DC do lewej strony auta.`,"1xxnsy2":`Osadź DevKit w dwóch listwach gniazd tak, by każda nazwa pinu na nim zgadzała się z nazwą nadrukowaną obok gniazda. Płytka przesunięta o jeden pin poda zasilanie na złe piny.`,ua2sfx:`Ustaw zworkę pinów V na 5 V, bo serwo, HC-SR04 i brzęczyk potrzebują 5 V. Płytki rozszerzeń się różnią, więc sprawdź oznaczenia zworki na swojej.`,"1jzloyj":`Czujnik`,"19ot7f3":`Głowica czujnika`,jii9ss:`HC-SR04 wysyła ultradźwiękowy impuls 40 kHz i mierzy czas echa: odległość w cm ≈ czas echa w µs ÷ 58. Mierzy od 2 cm do około 4 m w wiązce szerokiej na około 15°. Zamontowany na serwie SG90 może spojrzeć w lewo i w prawo, zanim auto skręci.`,"1s5nsw8":`Aby wyśrodkować serwo, wepnij je w złącze A5 shielda (brązowy na G) i wgraj dowolny szkic z kroku 9: oba ustawiają głowicę na 90°. Obracanie wałka wyjściowego na siłę może zniszczyć plastikowe zębatki. Przy takim montażu piny czujnika, patrząc od przodu, idą od lewej: GND, Echo, Trig, VCC.`,"3b6msg":`Aby wyśrodkować serwo, wepnij je w złącze GPIO 23 (brązowy na G, V ustawione na 5 V) i wgraj firmware z kroku 9, którego setup() wywołuje servoWrite(90). Obracanie wałka wyjściowego na siłę może zniszczyć plastikowe zębatki. Przy takim montażu piny czujnika, patrząc od przodu, idą od lewej: GND, Echo, Trig, VCC.`,"2934zx":`Mikroserwo SG90, jednoramienny orczyk i wkręty`,"1o4q0ha":`Uchwyt do serwa dla HC-SR04, z wkrętami`,"87cfw2":`Czujnik ultradźwiękowy HC-SR04`,"1bhe6w2":`Trzymaj serwo nad prostokątnym wycięciem z przodu środkowej płyty, wałkiem wyjściowym do góry i na osi auta. Przeciągnij wtyczkę w dół przez wycięcie, do tyłu pod płytą i w górę przez małą szczelinę za nim, i wyciągnij kabel, aż wtyczka leży na płycie obok kontrolera. Potem opuść serwo w wycięcie, z kablem schodzącym przez nacięcie na jego końcu, wsuń nadmiar kabla pod płytę, z dala od wałka silnika, i przykręć dwa uszy serwa do płyty.`,"7x26fs":`Wyśrodkuj serwo, potem wciśnij na jego wałek jednoramienny orczyk skierowany do przodu i przykręć go wkrętem orczyka.`,"3f8bcm":`Przykręć uchwyt do orczyka, pionowo, przodem do przodu.`,"178kb38":`Przykręć HC-SR04 z przodu uchwytu przez dwa narożne otwory jednej długiej krawędzi, tą krawędzią na dole i pinami na górze: wtedy przewody wychodzą w górę, z dala od serwa.`,"1jamndy":`Zasilanie`,tboesy:`Dwa ogniwa 18650 szeregowo dają nominalnie 7.4 V (8.4 V naładowane, około 6 V rozładowane). Włącznik przerywa przewód + baterii. Wszystko spotyka się we wtyku DC z zaciskami śrubowymi: dwa przewody baterii wchodzą do niego, wtyk zasila UNO przez jego gniazdo DC, którego stabilizator daje 5 V dla logiki, a dwa kolejne przewody z tych samych zacisków zasilają sterownik silników. Sterownik nie może brać zasilania z pinów 5 V shielda: pochodzą one z małego stabilizatora UNO, który cztery silniki by przeciążyły. Części, do których trzeba przylutować przewody, dostają je przy stole, zanim trafią na auto: najpierw nasuń kawałek rurki termokurczliwej na przewód, a potem obkurcz ją na lucie.`,r69l9i:`Dwa ogniwa 18650 szeregowo dają nominalnie 7.4 V (8.4 V naładowane, około 6 V rozładowane). Włącznik przerywa przewód + baterii. Wszystko spotyka się we wtyku DC z zaciskami śrubowymi: dwa przewody baterii wchodzą do niego, wtyk zasila płytkę rozszerzeń przez jej gniazdo DC, której stabilizatory dają 5 V i 3.3 V dla logiki, a dwa kolejne przewody z tych samych zacisków zasilają sterownik silników. Sterownik nie może brać zasilania z pinów 5 V płytki: pochodzą one z jej małego stabilizatora, który cztery silniki by przeciążyły. Części, do których trzeba przylutować przewody, dostają je przy stole, zanim trafią na auto: najpierw nasuń kawałek rurki termokurczliwej na przewód, a potem obkurcz ją na lucie.`,"175zcey":`Dwa razy sprawdź biegunowość przed włożeniem ogniw: gniazdo UNO ma plus w środku, a zacisk + wtyku to jego środkowy pin (sprawdź multimetrem). Ładuj, gdy pakiet spadnie do około 7 V, poniżej czego stabilizator UNO nie utrzyma 5 V. Jeśli nie zapali się żadna LED, natychmiast wyłącz i sprawdź okablowanie, zanim spróbujesz ponownie. LED i brzęczyk zostają na stole do kroku 8.`,t60ux3:`Dwa razy sprawdź biegunowość przed włożeniem ogniw: większość płytek rozszerzeń ma plus w środku, ale sprawdź symbol przy gnieździe, a zacisk + wtyku to jego środkowy pin (sprawdź multimetrem). Ładuj, gdy pakiet spadnie do około 7 V. Jeśli nie zapali się żadna LED, natychmiast wyłącz i sprawdź okablowanie, zanim spróbujesz ponownie. LED i brzęczyk zostają na stole do kroku 8.`,mvli44:`Górna płyta + 4 wkręty M3 × 6 mm`,"1dowjmo":`Koszyk 2 × 18650 z przewodami, 2 ogniwa`,"83x4u2":`Przełącznik suwakowy`,"1in9b4e":`Wtyk DC z zaciskami śrubowymi (plus w środku)`,l8wrh1:`Czerwona dioda LED 10 mm + rezystor 220 Ω`,"24gtky":`Brzęczyk aktywny 5 V`,"14zuroc":`Brzęczyk aktywny 5 V, tranzystor NPN + rezystor 1 kΩ`,"1pgj6ai":`Taśma piankowa, rurka termokurczliwa, 4 przewody połączeniowe do przecięcia: 2 czerwone, 2 czarne`,"1ewjpxi":`Taśma piankowa, rurka termokurczliwa, 5 przewodów połączeniowych do przecięcia: 2 czerwone, 2 czarne, 1 pomarańczowy`,y2bs3a:`Połóż górną płytę na czterech tulejkach 15 mm i przykręć ją.`,anc24f:`Przy stole przetnij czerwony przewód koszyka około 2 cm od koszyka. Przylutuj koniec od strony koszyka do skrajnego pinu włącznika, a 10 cm odciętego kawałka do środkowego pinu.`,"1mixan6":`Trzymaj koszyk nad górną płytą, przewodami do lewej strony auta. Przeciągnij czarny przewód w dół przez otwór przy lewej krawędzi płyty i prowadź go do przodu wzdłuż środkowej płyty, opuszczając koszyk. Przyklej koszyk dwoma paskami taśmy piankowej, a włącznik bokiem przy lewej krawędzi płyty, dźwignią na zewnątrz. Potem poprowadź czerwony przewód do przodu, za przedni róg płyty. Oba przewody powinny kończyć się obok gniazda DC kontrolera.`,"1xim7b6":`Przetnij czerwony i czarny przewód połączeniowy 12.5 cm od jednego końca. Wciśnij gniazdko dłuższego czerwonego kawałka na pin VCC sterownika silników, a dłuższego czarnego na GND, i poprowadź oba z powrotem wzdłuż lewej krawędzi środkowej płyty do gniazda.`,"1200i":`Przetnij czerwony i czarny przewód połączeniowy 11 cm od jednego końca. Wciśnij gniazdko dłuższego czerwonego kawałka na pin VCC sterownika silników, a dłuższego czarnego na GND, i poprowadź oba z powrotem wzdłuż lewej krawędzi środkowej płyty do gniazda.`,"1nymzxl":`Zdejmij 5 mm izolacji z czterech wolnych końców. Przykręć oba czerwone pod śrubę + wtyku, a oba czarne pod −, potem wciśnij wtyk w gniazdo DC UNO, obrócony tak, by + był na górze.`,f3jc5e:`Zdejmij 5 mm izolacji z czterech wolnych końców. Przykręć oba czerwone pod śrubę + wtyku, a oba czarne pod −, potem wciśnij wtyk w gniazdo DC płytki rozszerzeń, obrócony tak, by + był na górze.`,hhvzfi:`Przy stole przylutuj rezystor 220 Ω szeregowo do długiej (+) nóżki LED. Przetnij na pół czerwony i czarny przewód połączeniowy. Przylutuj jedną czerwoną połówkę do wolnego końca rezystora, a jedną czarną do krótkiej nóżki LED.`,"1qz1083":`Zegnij płasko dwa piny brzęczyka. Przylutuj drugą czerwoną połówkę do + (dłuższy pin, oznaczony na górze), a drugą czarną do −.`,"110bbxt":`Zegnij płasko dwa piny brzęczyka i przylutuj drugą czerwoną połówkę do + (dłuższy pin, oznaczony na górze). Przylutuj kolektor tranzystora do pinu −, a rezystor 1 kΩ do jego bazy, potem pół pomarańczowego przewodu połączeniowego do rezystora i drugą czarną połówkę do emitera. Obkurcz jedną rurkę na tranzystorze i rezystorze. Sprawdź w karcie katalogowej swojego tranzystora, która nóżka jest która.`,"1avlub7":`Sprawdź, czy żaden goły lut nie może dotknąć innego i czy włącznik jest wyłączony. Potem włóż dwa ogniwa do koszyka, każdy koniec + tam, gdzie koszyk pokazuje +. Włącz na chwilę: diody zasilania na kontrolerze i na sterowniku silników powinny się zapalić.`,k2hc2b:`Okablowanie`,s234wa:`Podłącz przewody`,"1po8toc":`Każdy czujnik i element wykonawczy wpina się w złącze G / V / S na shieldzie, więc wszystkie dzielą masę UNO; masa sterownika pochodzi z baterii, czyli przez wtyk DC jest to ta sama masa. Piny dobrano według miejsca każdej części, więc przewody rozchodzą się ze złączy bez krzyżowania. Pracuj w tej kolejności, przy wyłączonym włączniku: najpierw LED, nisko przy lewym końcu złącza, a na końcu cztery przewody czujnika, bo przechodzą łukiem nad wszystkim innym. Przewód połączeniowy zakłada się po jednym końcu: wciśnij jedno gniazdko do końca na pin, zegnij przewód, wciśnij drugie. Najedź na wiersz, aby zobaczyć przewód na modelu.`,"1ylwoyd":`Każdy czujnik i element wykonawczy wpina się w złącze G / V / S na płytce rozszerzeń, więc wszystkie dzielą masę ESP32; masa sterownika pochodzi z baterii, czyli przez wtyk DC jest to ta sama masa. Piny dobrano według miejsca każdej części, więc przewody rozchodzą się ze złączy bez krzyżowania. Pracuj w tej kolejności, przy wyłączonym włączniku: najpierw LED, nisko przy lewym końcu złącza, a na końcu przewody czujnika, bo przechodzą łukiem nad wszystkim innym. Przewód połączeniowy zakłada się po jednym końcu: wciśnij jedno gniazdko do końca na pin, zegnij przewód, wciśnij drugie. Najedź na wiersz, aby zobaczyć przewód na modelu.`,"10tvb2g":`D5 i D11 niosą prędkość każdej strony: to piny PWM, które działają dalej, gdy pracuje biblioteka Servo (przejmuje ona Timer1, co wyłącza PWM na D9 i D10). D6 i D12 niosą kierunek. Serwo i brzęczyk używają A5 i A0 jako zwykłych pinów cyfrowych. Wszystkie piny G są połączone, podobnie wszystkie piny V: GND i VCC czujnika mogą trafić na najbliższe.`,it0an4:`Dzielnik 1 kΩ / 2 kΩ zamienia impuls Echo 5 V na 3.3 V (5 V × 2 ⁄ 3). Echo używa GPIO 35, jednego z pinów tylko wejściowych (34–39): musi jedynie czytać. Brzęczyk jest zasilany z pinu V 5 V, a tranzystor go przełącza, bo 3.3 V to mniej, niż potrzebuje brzęczyk 5 V. Wyjścia omijają GPIO 0, 2, 5, 12, 14 i 15, które są pinami strapping albo pulsują podczas startu ESP32. Wszystkie piny G są połączone, podobnie wszystkie piny V.`,"16ffufp":`LED: przyklej obok lewego przedniego rogu kontrolera · czerwony → S · czarny → G`,"55vkwv":`Sterownik A-IA / A-IB (lewa)`,"1wr2rcy":`Sterownik B-IA / B-IB (prawa)`,"12y58k1":`Kabel serwa (brązowy G, czerwony V, pomarańczowy S)`,"1xjcvwz":`Brzęczyk: przyklej z przodu górnej płyty · czerwony → S · czarny → G`,"1h6hx3u":`HC-SR04 Trig → S · VCC → V · GND → G pinu D2`,zvbj2f:`HC-SR04 Echo`,"83uabx":`Brzęczyk: przyklej z przodu górnej płyty · czerwony → V · pomarańczowy (baza) → S · czarny (emiter) → G`,"1eb7xia":`HC-SR04 Trig → S · VCC → V · GND → G pinu GPIO 34`,"1ig2p4r":`HC-SR04 Echo: przetnij jego przewód 4.5 cm od jednego końca · 1 kΩ między kawałkami · 2 kΩ dalej do 4.7 cm odciętych z końca czarnego przewodu · krótkie kawałki → S i G`,xoaiok:`Kod`,"1if8prf":`Program`,"1g03ums":`Wgraj kod`,"1bv2ey7":`Dwa szkice. Test okablowania sprawdza po kolei każdą część, więc widzisz, że każda jest podłączona i że obie strony kręcą się we właściwą stronę. Omijanie przeszkód to program auta: jedzie, aż coś jest bliżej niż 22 cm, rozgląda się głowicą w prawo i w lewo i skręca w stronę z większą ilością miejsca.`,"8lzj5q":`Ten firmware zamienia ESP32 w punkt dostępowy Wi-Fi. Wykonuje polecenia, które wysyła RoboKit (jazda, prędkość, tryb, serwo, LED i brzęczyk), zatrzymuje się, gdy przestają przychodzić, i 10 razy na sekundę odsyła odległość i stan silników. W trybie Auto sam omija przeszkody, tą samą procedurą, którą wykonuje symulator.`,saufbh:`Gdy nic nie odbija impulsu, HC-SR04 trzyma Echo w stanie wysokim przez około 38 ms (wartość z karty katalogowej; niektóre moduły dłużej). To więcej niż limit 30 ms, więc pulseIn() zwraca 0. Program omijania liczy to jako 400 cm, „wolne”, a nie „dotyka”. Wiązka jest wąska, więc auto może zahaczyć o róg, którego nigdy nie widziało: odczyt, który przestaje się zmieniać, gdy koła pchają, mówi mu, że utknęło. A gdy jest znów zablokowane zaraz po skręcie, skręca jeszcze raz w tę samą stronę zamiast z powrotem: w rogu skręcałoby inaczej w lewo, w prawo, w lewo bez końca.`,"11hew0t":`ledcAttach() i ledcWrite(pin, duty) to API arduino-esp32 3.x; starsze wywołania ledcSetup() i ledcAttachPin() z wersji 2.x już się nie kompilują. Wiązka czujnika jest wąska, więc w trybie Auto auto może zahaczyć o róg, którego nigdy nie widziało: odczyt, który przestaje się zmieniać, gdy koła pchają, mówi mu, że utknęło. A gdy jest znów zablokowane zaraz po skręcie, skręca jeszcze raz w tę samą stronę zamiast z powrotem: w rogu skręcałoby inaczej w lewo, w prawo, w lewo bez końca.`,"3zk06m":`W Arduino IDE wybierz Tools → Board → Arduino UNO i właściwy port. Oba szkice używają biblioteki Servo, dołączonej do IDE.`,j0z2nr:`Podeprzyj auto tak, by wszystkie cztery koła nie dotykały stołu. Wgraj test okablowania, włącz baterię i otwórz Serial Monitor z prędkością 115200 bodów. Obserwuj, jak dzieje się każda numerowana linia: LED i pisk, głowica w prawo, w lewo i na środek, potem każda strona do przodu i do tyłu.`,"1dz2oap":`Popraw to, co się nie zgadzało (patrz lista poniżej). Potem wgraj omijanie przeszkód, odłącz kabel USB, postaw auto na podłodze i włącz: odczeka dwie sekundy, a potem ruszy.`,"4czqhs":`Zmieniaj TURN_MS w szkicu, aż każdy skręt na twojej podłodze będzie mniej więcej ćwierć obrotu.`,rgjhux:`W Arduino IDE dodaj https://espressif.github.io/arduino-esp32/package_esp32_index.json w File → Preferences → Additional boards manager URLs. Potem zainstaluj „esp32 by Espressif Systems” w wersji 3.x z Boards Manager i wybierz ESP32 Dev Module.`,"118rr9r":`Z Library Manager zainstaluj najnowszy „WebSockets” autorstwa Markusa Sattlera i „ArduinoJson” w wersji 7 autorstwa Benoita Blanchona.`,nbb8bl:`Wgraj, potem podeprzyj auto tak, by wszystkie cztery koła nie dotykały stołu, i włącz baterię. Połącz się z siecią Wi-Fi „RoboKit” (hasło drive1234), przejdź do kroku 10 i połącz się przez Ustawienia → Prawdziwe auto (Wi-Fi ESP32).`,srtywe:`Wypróbuj po kolei każde sterowanie: LED, brzęczyk, suwak serwa, potem W A S D. Jeśli któraś strona kręci się w złą stronę, patrz lista poniżej. Potem postaw auto na podłodze, wypróbuj Auto i zmieniaj TURN_MS, aż każdy skręt będzie mniej więcej ćwierć obrotu.`,sp50jr:`Po włączeniu nic się nie świeci`,"1gg4m0p":`Wyłącz. Sprawdź, czy ogniwa są naładowane i włożone właściwą stroną, czy czerwone przewody są pod śrubą + wtyku i czy włącznik jest podłączony między środkowym pinem a jednym skrajnym.`,"9crnd5":`W teście jedna strona kręci się do tyłu`,"1mf4jfi":`Zamień dwa przewody tej strony w jej zacisku śrubowym: MOTOR-A to lewa strona, MOTOR-B prawa.`,"1gcvytv":`Jedno koło kręci się przeciw swojemu partnerowi`,"76bppn":`Zamień dwa przewody tego jednego silnika w miejscu, gdzie są skręcone z przewodami drugiego silnika.`,kakgt9:`Linia 3 kręci prawymi kołami`,"95tfvz":`Dwie pary przewodów są zamienione: A-IA / A-IB idą do D11 / D12, B-IA / B-IB do D5 / D6.`,"1yvpqg9":`Głowica patrzy najpierw w lewo`,"3fc0ov":`Niektóre serwa kręcą się odwrotnie: zamień 20 i 160 w szkicach.`,"1ymivbo":`Odległość wynosi zawsze 0.0 cm`,"1wzcqly":`Nie wraca żadne echo. Sprawdź, czy Trig jest na D4, a Echo na D3, i czy VCC i GND czujnika są na pinie V i pinie G. Czujnik pokazuje też 0, gdy w promieniu około 4 m nic nie ma.`,lg1f33:`UNO restartuje się, gdy ruszają silniki`,gp3cr0:`Napięcie baterii spada: naładuj ogniwa. Kondensator 470–1000 µF między V a G na shieldzie (uważaj na biegunowość) pomaga zasilaniu 5 V przetrwać spadki.`,"13n04wo":`Auto buczy, ale nie obraca się w miejscu`,y7q52i:`Przy skręcie wszystkie cztery opony szorują bokiem, co wymaga więcej siły niż jazda prosto: zwiększ SPIN w stronę MAX_PWM i naładuj ogniwa.`,hvphiw:`Ściąga na jedną stronę`,ittf4s:`Żadne dwa silniki nie są identyczne. Zwolnij szybszą stronę: dla auta, które ściąga w prawo, drive(CRUISE - 10, CRUISE).`,"19do8xl":`Wgrywanie zatrzymuje się na „Connecting…”`,hn5crr:`Przytrzymaj przycisk BOOT na DevKit, aż zacznie się wgrywanie, i sprawdź, czy kabel USB przesyła dane, a nie tylko zasilanie.`,"144ggw6":`RoboKit nie może się połączyć`,"1wm6oj5":`Jedna strona kręci się do tyłu`,"1buhj6h":`Lewa i prawa są zamienione`,"1s6olzj":`Dwie pary przewodów są zamienione: A-IA / A-IB idą do GPIO 26 / 27, B-IA / B-IB do GPIO 33 / 25.`,svln7p:`W trybie Auto głowica patrzy najpierw w lewo`,"1ki0m9i":`Niektóre serwa kręcą się odwrotnie: zamień 20 i 160 w autoStep().`,"6xg3a":`Odległość wynosi zawsze 400 cm`,"7himiv":`Nie wraca żadne echo. Sprawdź, czy Trig jest na GPIO 32, czy Echo dochodzi do GPIO 35 przez dzielnik i czy VCC czujnika jest na pinie 5 V. Czujnik pokazuje też 400, gdy w promieniu około 4 m nic nie ma.`,ksb87p:`Brzęczyk milczy`,"9czfii":`Sprawdź nóżki tranzystora z jego kartą katalogową (kolejność różni się między typami) i czy + brzęczyka jest na pinie 5 V.`,igpqu0:`ESP32 restartuje się, gdy ruszają silniki`,owaty5:`Napięcie baterii spada: naładuj ogniwa. Kondensator 470–1000 µF między pinem 5 V a G (uważaj na biegunowość) pomaga zasilaniu przetrwać spadki.`,"1u5gnnb":`Przy skręcie wszystkie cztery opony szorują bokiem, co wymaga więcej siły niż jazda prosto: zwiększ prędkość i naładuj ogniwa.`,uak3xr:`1 · Test okablowania`,"1jz093b":`2 · Omijanie przeszkód`,"129dlzg":`Firmware`,ussxe7:`Symulacja`,"17ssthc":`Pojeździj`,bmzqy4:`Symulowane auto ma te same części co twoje. Pojeździj nim po arenie testowej, potem przełącz na Auto: wykonuje tę samą procedurę co szkic omijania przeszkód. Zatrzymuje się i piszczy przy przeszkodzie, patrzy w prawo i w lewo, skręca w stronę z większą ilością miejsca i cofa się, gdy utknie.`,"189d210":`Symulowane auto odpowiada na te same polecenia, które RoboKit wysyła do twojego ESP32, a Auto wykonuje tę samą procedurę co firmware. Gdy twoje auto będzie zbudowane, przełącz się na nie w Ustawienia → Prawdziwe auto (Wi-Fi ESP32).`,olmdkx:`Koło, 65 mm`,psly3z:`Napęd`,vffqvh:`Gumowa opona na plastikowej feldze. Piasta ma gniazdo z dwoma spłaszczeniami, które wciska się na wałek wyjściowy silnika TT, więc koło nie może się obracać na wałku. Gdy auto obraca się w miejscu, opony szorują bokiem, więc przyczepność ma znaczenie.`,jq4v4c:`Piasta`,mq93xq:`gniazdo z dwoma spłaszczeniami na wałek silnika TT`,"1cgpuek":`Droga na obrót`,esl998:`≈ 20.4 cm (π × 6.5 cm)`,"11yszgp":`Silnik TT z przekładnią`,m5llum:`Mały szczotkowy silnik DC napędzający plastikową przekładnię 1:48. Odwróć prąd, a koło kręci się w drugą stronę; obniż średnie napięcie za pomocą PWM, a zwalnia.`,"525amd":`Napięcie`,"226us9":`Przełożenie`,jpnnsq:`≈ 200 rpm przy 6 V, bez obciążenia`,"1dw4k8q":`Prąd`,"1p9wnb6":`≈ 150 mA bez obciążenia · do ≈ 1.5 A przy zablokowaniu, 6 V`,cdauuh:`Moment przy zablokowaniu`,"1gzxf67":`≈ 0.8 kg·cm przy 6 V`,ign4wl:`Korpus`,mad9cv:`Wałek`,"14e36jb":`Ø 5.5 mm z dwoma spłaszczeniami w odstępie 3.7 mm, wystający z obu stron`,feutd2:`Mocowanie`,"183nrmx":`dwa otwory Ø 3 mm w odstępie 17.5 mm, 20 mm za wałkiem`,"108seeu":`Uchwyt silnika`,"1mquwkf":`Podwozie`,"10qeeg1":`Kawałek akrylu w kształcie litery T. Jego trzon wychodzi w górę przez dolną płytę obok przekładni, a głowa zostaje pod spodem, więc nie może się przesunąć. Po jednym idzie z każdej strony silnika, a dwie długie śruby przechodzą przez oba uchwyty i dwa otwory montażowe przekładni.`,"1kk17cw":`Materiał`,"1me4wyg":`akryl`,st0e1p:`Na silnik`,"8uzq1j":`2 uchwyty · 2 śruby M3 × 30 + nakrętki`,"1am47c9":`Montaż`,v6cwyh:`od spodu płyty: wewnętrzny w szczelinie, zewnętrzny w wycięciu w krawędzi`,"723pu9":`Niesie cztery silniki i osiem tulejek środkowej płyty. Szczelina i wycięcie w krawędzi obok każdego silnika przyjmują dwa uchwyty tego silnika.`,"1n7meho":`Wymiary (ten model)`,r4lxco:`Podłoga dla elektroniki. Długa szczelina na środku przepuszcza przewody silników od spodu, a prostokątne wycięcie z przodu trzyma serwo; nacięcie na jego końcu jest na kabel serwa.`,"11vqw8c":`25 mm nad dolną płytą`,"1957t19":`Górna płyta`,"2ljc6y":`Płyta o połowie długości z tyłu, która trzyma pakiet baterii, włącznik i brzęczyk nad elektroniką.`,"1ytak7b":`1.5 cm nad środkową płytą`,"1ey525v":`Mosiężna tulejka dystansowa, M3`,"7je4w9":`Sześciokątne dystanse z gwintem na obu końcach. Trzymają płyty w odstępie i unoszą płytki drukowane nad akrylem, aby nic na ich spodzie go nie dotykało.`,"1t2znv5":`Gwint`,i9dhsi:`M3, wewnętrzny–wewnętrzny`,"1cazjzs":`dolna → środkowa płyta (ponad silnikami 22 mm)`,rni6ay:`środkowa → górna płyta`,"1dz3bjd":`płytka kontrolera`,"1erre2c":`Wkręty`,"7fsd49":`M3 × 6 mm na każdym końcu, razem 32`,pmsrct:`Przewody silników`,h0ivdz:`Czerwony i czarny przewód z każdego silnika: czerwony na blaszce bliżej środka auta, czarny na tej bliżej koła. Dwa silniki z każdej strony są połączone równolegle do jednego kanału sterownika, czerwony z czerwonym i czarny z czarnym, więc zawsze kręcą się razem.`,"148isqp":`każdy około 15 cm`,"88dh10":`Lewa para`,"1hr3y9w":`MOTOR-A`,"1gp3zrj":`Prawa para`,"1il2rct":`MOTOR-B`,"4iibl6":`Strona kręci się do tyłu?`,"1p9lbgb":`zamień jej dwie pary w zacisku`,"2380z5":`Koło przeciw partnerowi?`,h5sbfv:`zamień dwa przewody tego silnika`,"19qn9l6":`Sterownik silników L9110S`,"82whm4":`Elektronika`,"12ibf8u":`Dwa układy L9110S z mostkiem H, po jednym na kanał. Każdy kanał ma dwa wejścia: IA wysokie i IB niskie kręcą silnikiem w jedną stronę, IA niskie i IB wysokie w drugą, a oba jednakowe go zatrzymują. PWM na jednym wejściu ustawia prędkość.`,"25ul91":`Zasilanie (VCC)`,m2phlf:`800 mA na kanał (1.5–2 A szczytowo)`,"17s6ks8":`Wejścia`,d0m2ee:`A-IA, A-IB, B-IA, B-IB · logika 3.3 V lub 5 V`,"4swwow":`Złącze`,oja0mi:`B-IA · B-IB · GND · VCC · A-IA · A-IB (piny kątowe)`,"1xbblqt":`około 29 × 23 mm, otwory montażowe Ø 3 mm (wymiary zależą od sprzedawcy)`,"189a81e":`Płytka z mikrokontrolerem ATmega328P. Uruchamia twój szkic, czyta czujnik i decyduje, co robią silniki.`,"1ebaepz":`ATmega328P @ 16 MHz`,"16qkmtv":`Poziom logiki`,eslzkd:`Piny PWM`,oopaku:`Pamięć`,"8hfwsd":`32 KB flash · 2 KB RAM`,"1jzh7y5":`Zasilanie`,"1vbs2jm":`7–12 V na gnieździe DC (zalecane)`,"1hxwxrt":`Prąd pinu`,xms582:`20 mA zalecane · 40 mA maksimum bezwzględne`,"1n28mf4":`Wpina się na UNO i wyprowadza każdy pin na 3-pinowe złącze G / V / S (masa, 5 V, sygnał), więc serwo lub czujnik wpina się bezpośrednio z własną masą i zasilaniem.`,e8ir2h:`Złącza`,d0uaj4:`D0–D13 i A0–A5, każde G · V · S`,"1iy90zn":`Piny V`,ohp32m:`5 V z UNO, dopóki założona jest zworka SEL`,"1y4aysj":`Bez zworki`,gi4ocs:`V pochodzi z zacisku śrubowego shielda`,"1thlwjq":`Uwaga`,"1fzsig9":`nigdy nie zasilaj zacisku śrubowego przy założonej SEL`,"1kft85q":`Dodatki`,"1e4238k":`złącza I²C i szeregowe`,"1jeelmn":`ESP32 DevKit + płytka rozszerzeń`,"8jd2d6":`Dwurdzeniowy mikrokontroler z Wi-Fi i Bluetooth, osadzony na płytce rozszerzeń, która dodaje gniazdo DC ze stabilizatorem i złącze G / V / S dla każdego pinu.`,"1inmx8d":`Moduł`,qx458t:`ESP32-WROOM-32 · do 240 MHz`,"7ra2ga":`3.3 V, nie znosi 5 V`,"1chl2hi":`dowolny pin wyjściowy (LEDC)`,"7fk3dd":`Łączność`,"1b7zmuj":`Wi-Fi 802.11 b/g/n · Bluetooth`,pawwts:`≈ 6.5–12 V na gnieździe DC (sprawdź swoją płytkę)`,yzyhje:`3.3 V lub 5 V, ustawiane zworką`,"7wntef":`Mikroserwo SG90`,mni0ct:`Mały silnik, przekładnia i czujnik położenia w jednej obudowie. Oczekuje impulsu co 20 ms (50 Hz); szerokość impulsu ustala kąt: 1.5 ms to środek, a około 0.5–2.4 ms obejmuje od 0° do 180°.`,wvoosj:`Moment obrotowy`,"1e13gca":`≈ 0.1 s na 60°`,"1yo9wk7":`Wymiary · masa`,"1oaes5p":`23 × 12 × 29 mm · 9 g`,"1b34x3l":`Przewody`,"1qalf36":`brązowy GND · czerwony V+ · pomarańczowy sygnał`,"1bshntj":`Uchwyt do serwa dla HC-SR04`,"1yr5sge":`Przykręca się do orczyka serwa i trzyma HC-SR04 za dwa jego narożne otwory, więc czujnik obraca się z serwem, a jego wiązka pozostaje pozioma.`,"1t4m9bk":`Mocowanie`,mnle4w:`wkręty orczyka serwa`,"1yzxd81":`Trzyma`,"1fp9bdu":`HC-SR04 za dwa jego narożne otwory, na dystansach`,"1yozvc2":`Inne rodzaje`,"16fhes5":`wiele uchwytów chwyta czujnik zamiast tego za jego dwa przetworniki`,c8gdr7:`Impuls 10 µs na Trig sprawia, że jeden przetwornik wysyła osiem okresów 40 kHz; drugi nasłuchuje. Echo pozostaje potem w stanie wysokim tak długo, jak dźwięk leciał tam i z powrotem, więc cm = µs ÷ 58 (343 m/s, podzielone na pół).`,"198uyr6":`Zasięg`,"3xsn4q":`Wiązka`,"1gw4v0v":`poniżej 15°`,"1oy2zwu":`Zasilanie`,"1m7niep":`Częstość impulsów`,"7gsn1j":`jeden co 60 ms lub rzadziej`,npm5w4:`Piny (przód, od lewej → w prawo)`,pyp646:`VCC · Trig · Echo · GND z pinami na dole; zamontowany pinami do góry, jak tutaj: GND · Echo · Trig · VCC`,cr1wqh:`Pakiet Li-ion 2 × 18650`,"1fdnj4z":`Dwa ogniwa szeregowo: 8.4 V naładowane, 7.4 V nominalnie, około 6 V rozładowane. Używaj ogniw z zabezpieczeniem, nigdy ich nie zwieraj i ładuj je w porządnej ładowarce Li-ion.`,w63ube:`7.4 V nominalnie (6–8.4 V)`,serueh:`Pojemność`,"1lup9sh":`2000–3500 mAh (oryginalne ogniwa)`,"7l22en":`Koszyk`,"1ka7i4l":`na 2 ogniwa, szeregowo`,"1h1ba5m":`ogniwa z zabezpieczeniem są o kilka mm dłuższe; sprawdź, czy się mieszczą`,h4px5m:`Włącznik zasilania`,bs7ocz:`Przerywa przewód + baterii, więc całe auto jest wyłączone. Jest podłączony między środkowym pinem a jednym skrajnym: czerwony przewód koszyka na jednym, przewód do wtyku na drugim. Leży bokiem na taśmie piankowej przy lewej krawędzi górnej płyty, dźwignią na zewnątrz, gdzie palec łatwo go dosięgnie.`,"1m2zofh":`Typ`,"69jc9h":`przełącznik suwakowy SPDT używany jako wł./wył.`,w3vkqt:`Piny`,"1owufyi":`trzy w rzędzie: skrajny · wspólny · skrajny`,fph5dc:`Obciążalność`,"1bpycfc":`wybierz taki na ≥ 2 A DC`,k3s7zg:`Brzęczyk aktywny, 5 V`,"177ed2m":`Sygnalizacja`,jfbt4g:`Ma własny oscylator: ustaw pin na HIGH, a piszczy o stałej wysokości, bez kodu tone(). Pobiera do około 25–30 mA: mieści się w bezwzględnym maksimum pinu 40 mA, ale przekracza zwykle zalecane 20 mA, więc przełączanie go tranzystorem NPN jest łagodniejszym nawykiem.`,xscire:`Ma własny oscylator: podaj zasilanie, a piszczy o stałej wysokości. Brzęczyki aktywne 5 V działają od około 3.5–4 V w górę, więc pin 3.3 V nie poprowadzi go niezawodnie. Tutaj jest zasilany z pinu V 5 V, a przełącza go tranzystor NPN sterowany przez GPIO 21.`,"1p7q9i9":`Ton`,"17n9x61":`≈ 2.3 kHz`,z19kz7:`Napięcie znamionowe`,"2tl42a":`5 V (działa od ≈ 3.5–4 V, zależnie od producenta)`,"1udh5u4":`≈ 25–30 mA przy 5 V`,"1xat3vm":`w odstępie 7.6 mm`,"1yzktex":`Biegunowość`,"1tmcwg9":`dłuższy pin / „+” na górze = +`,i8lb7k:`Czerwona dioda LED 10 mm`,"513nhj":`Prąd płynie od długiej nóżki (anoda, +) do krótkiej (katoda, −, przy spłaszczeniu obrzeża). Zawsze potrzebuje rezystora szeregowo. Tutaj leży bokiem obok lewego przedniego rogu kontrolera i świeci na lewo od auta.`,"17jikfo":`Napięcie przewodzenia`,"1g61wql":`maks. 20 mA`,u532rf:`Rezystor 220 Ω`,"17qhgqf":`Ogranicza prąd LED: (5 V − 2 V) ÷ 220 Ω ≈ 14 mA. Paski kolorów: czerwony, czerwony, brązowy: 2, 2 i × 10 = 220 Ω.`,"1kwszon":`Ogranicza prąd LED: (3.3 V − 2 V) ÷ 220 Ω ≈ 6 mA. Paski kolorów: czerwony, czerwony, brązowy: 2, 2 i × 10 = 220 Ω.`,zzpczz:`Paski`,"7ytjo4":`czerwony · czerwony · brązowy · złoty`,"1llx3uw":`Tolerancja`,"3389ey":`Dzielnik Echo · 1 kΩ + 2 kΩ`,i8pnlw:`Wyjście Echo HC-SR04 dochodzi do 5 V, ale piny ESP32 przyjmują najwyżej 3.3 V. Dwa rezystory szeregowo od Echo do masy tworzą dzielnik: GPIO czyta napięcie na rezystorze 2 kΩ, 5 V × 2 kΩ ÷ (1 kΩ + 2 kΩ) ≈ 3.3 V.`,"15yc2v4":`Paski 1 kΩ`,"89urq0":`brązowy · czarny · czerwony · złoty`,"1ypqwgn":`Paski 2 kΩ`,"1ywrkmt":`czerwony · czarny · czerwony · złoty`,"12k1o0e":`Echo → 1 kΩ → GPIO 35 · 2 kΩ od GPIO 35 do G`,aarp77:`Potrzebny dla`,"15e8vss":`tylko ESP32`,"1aqlq1n":`Tranzystor brzęczyka · NPN + 1 kΩ`,vudz42:`Tranzystor NPN działa jak przełącznik: mały prąd w bazie pozwala płynąć większemu od kolektora do emitera. GPIO 21 steruje bazą przez 1 kΩ, (3.3 V − 0.7 V) ÷ 1 kΩ ≈ 2.6 mA, czyli aż nadto, by przełączyć ≈ 30 mA brzęczyka z pinu 5 V.`,"1gy1kba":`Tranzystor`,"62rwh2":`PN2222A, S8050 lub podobny NPN`,"1tlwyig":`Kolektor`,"18vf2cp":`− brzęczyka`,"19phq7s":`Baza`,hrttng:`1 kΩ → S pinu GPIO 21`,"10ztoj1":`Emiter`,"1m0unsb":`G pinu GPIO 21`,"16l0jzg":`Nóżki`,v4q23:`sprawdź układ wyprowadzeń w karcie katalogowej`,gy95h:`Przewód montażowy`,"170hkbj":`Czerwony i czarny przewód linkowy na przewody silników. Tnij go na długość w trakcie pracy.`,"19d4ccc":`Czerwony`,ch832v:`blaszka bliżej środka auta, w każdym silniku`,bxogn8:`Czarny`,"1xdely8":`blaszka bliżej koła`,"114bxvb":`Przewody połączeniowe żeńsko-żeńskie`,tq3ghm:`Przewody Dupont z gniazdkiem na obu końcach, które wciska się na piny złączy w rastrze 2.54 mm. Wejścia sterownika i czujnik dostają jeden cały przewód na pin. Przecięty na pół przewód daje przewody z gniazdkiem na jednym końcu: dla lutowanych części (LED, brzęczyk) i dla zasilania sterownika, którego drugie końce idą pod śruby wtyku.`,xe6ekx:`Raster`,terfe0:`15 cm (20 cm też działają: zostawiają większe pętle)`,q9r4h7:`Użyte w całości`,"16oowgw":`8: cztery wejścia sterownika, cztery piny czujnika`,"1rf1gzr":`7: cztery wejścia sterownika, trzy piny czujnika`,onu7hf:`Przecięte`,"38aacf":`4: czerwony i czarny na pół na przewody LED i brzęczyka, czerwony i czarny 12.5 cm od jednego końca na zasilanie sterownika`,"3iidc0":`6: czerwony i czarny na pół na przewody LED i brzęczyka, pomarańczowy na pół na bazę tranzystora, czerwony i czarny 11 cm od jednego końca na zasilanie sterownika, i przewód Echo czujnika na jego dzielnik`,"14fe75h":`Przewody połączeniowe · czujnik ultradźwiękowy`,f96u6l:`Cztery przewody ze złącza czujnika, które jest na górze, wracają łukiem do shielda. Do VCC i GND wystarczy dowolny pin V i dowolny pin G: użyte są najbliższe, więc cztery przewody rozchodzą się obok siebie.`,tuihok:`Cztery przewody ze złącza czujnika, które jest na górze, wracają łukiem do płytki rozszerzeń. Echo to sygnał 5 V, więc przechodzi przez dzielnik 1 kΩ / 2 kΩ (wlutowany w jego przewód, pod rurką termokurczliwą), zanim dotrze do GPIO 3.3 V.`,ftyyiy:`V pinu D4`,"1xuokt7":`Trig`,o3rtpx:`S pinu D4`,gi87tw:`Echo`,m5ulv4:`S pinu D3`,y9urxb:`G pinu D2`,"1n4125d":`V pinu GPIO 32 (ustawione na 5 V)`,p5iwlb:`S pinu GPIO 32`,"1aj3mnm":`1 kΩ → S pinu GPIO 35 · 2 kΩ stamtąd do jego G`,p0bbcd:`G pinu GPIO 34`,"1kn37ri":`Przewody połączeniowe · sterownik silników`,oiporr:`Cztery wejścia sterownika. Każda para steruje jedną stroną auta: IA niesie jej prędkość, na pinie PWM, a IB jej kierunek.`,z48w8g:`Cztery wejścia sterownika, każde na pinie obsługującym PWM. Każda para steruje jedną stroną auta.`,"11ubulz":`A-IA / A-IB (lewa)`,jf4uze:`B-IA / B-IB (prawa)`,"15oeqsr":`Kabel serwa`,wowqjs:`Własny trzyżyłowy przewód serwa. Schodzi w dół przez wycięcie i wraca w górę przez szczelinę obok, z powrotem wzdłuż płyty obok kontrolera i na tylne złącze; nadmiar jest złożony pod płytą. Jego 3-stykowa wtyczka pasuje od razu do złącza G / V / S: brązowy na G.`,v89fad:`Własny trzyżyłowy przewód serwa. Schodzi w dół przez wycięcie i wraca w górę przez szczelinę obok, z powrotem wzdłuż płyty obok kontrolera i na tylne złącze; nadmiar jest złożony pod płytą. Jego 3-stykowa wtyczka pasuje od razu do złącza G / V / S: brązowy na G. Rząd V musi być ustawiony na 5 V.`,r6nyn:`Brązowy`,"1u2gqme":`Pomarańczowy (sygnał)`,"1qoi1mz":`S pinu A5`,ovg5ed:`S pinu GPIO 23`,"1uovlnp":`Przewody LED`,"1mffxae":`Pół czerwonego i pół czarnego przewodu połączeniowego, przylutowane do LED, z gniazdkiem na drugim końcu. Anoda idzie przez rezystor 220 Ω do pinu sygnałowego; katoda do masy.`,elp8sy:`Anoda (przez 220 Ω)`,k62hvj:`S pinu D13`,ilk009:`Katoda`,k48vv7:`G pinu D13`,tbj8zu:`S pinu GPIO 13`,imqrdy:`G pinu GPIO 13`,"1indwkw":`Przewody brzęczyka`,"1c2cbqo":`Pół czerwonego i pół czarnego przewodu połączeniowego przylutowane do pinów brzęczyka. Ustaw przewód + na HIGH, aby zapiszczał.`,epsmo4:`Brzęczyk jest między pinem V 5 V a tranzystorem. Ustaw GPIO 21 na HIGH, a tranzystor łączy − brzęczyka z masą, więc ten piszczy.`,"1rigupw":`S pinu A0`,"1yvwce0":`G pinu A0`,"1tndblu":`V pinu GPIO 21 (5 V)`,i73cl5:`kolektor tranzystora`,a4pty4:`Baza (przez 1 kΩ)`,obgy0f:`S pinu GPIO 21`,g663eg:`Okablowanie zasilania`,wp3j1m:`Wszystko spotyka się we wtyku DC z dwoma zaciskami śrubowymi, wciśniętym w gniazdo DC UNO. Plus baterii dochodzi do zacisku + przez włącznik; minus baterii idzie prosto do zacisku −. Drugi czerwony i drugi czarny przewód pod tymi samymi dwiema śrubami doprowadzają napięcie baterii do pinów VCC i GND sterownika. Sterownika nie da się zamiast tego zasilić z pinów 5 V shielda: zasila je stabilizator UNO, który daje najwyżej kilkaset mA.`,"1gazt2h":`Wszystko spotyka się we wtyku DC z dwoma zaciskami śrubowymi, wciśniętym w gniazdo DC płytki rozszerzeń. Plus baterii dochodzi do zacisku + przez włącznik; minus baterii idzie prosto do zacisku −. Drugi czerwony i drugi czarny przewód pod tymi samymi dwiema śrubami doprowadzają napięcie baterii do pinów VCC i GND sterownika. Sterownika nie da się zamiast tego zasilić z pinów 5 V płytki: zasila je jej stabilizator, który daje najwyżej kilkaset mA.`,"1wuyp3l":`+ baterii (przez włącznik)`,"161fdmk":`− baterii = GND`,"6j9255":`Wtyk`,"1qkac6a":`wtyk 5.5 × 2.1 mm, plus w środku, z zaciskami śrubowymi`,"1s864ea":`Pod każdą śrubą`,wj14kx:`dwa przewody: jeden z baterii, jeden do sterownika`,oz5l6a:`Omijanie przeszkód`,zj0mwn:`Zmierz odległość`,"9jogsy":`Przy każdym obiegu loop() czujnik wysyła impuls. Szkic zapamiętuje też, kiedy odczyt ostatnio zmienił się o więcej niż {changeCm} cm: odczyt, który stoi w miejscu, gdy koła pchają, zdradzi mu, że auto utknęło.`,"1va2b8a":`Droga wolna?`,yssn5p:`Czy droga jest wolna?`,zou1hc:`Wolna oznacza, że nic nie jest bliżej niż {stopCm} cm (STOP_CM), a odczyt wciąż się zmienia. Wtedy auto jedzie dalej i pyta ponownie {pingMs} ms później.`,"164owbk":`Jedź dalej`,"2guryp":`LED zgaszona, obie strony do przodu z prędkością CRUISE i {pingMs} ms czekania: tyle czujnik potrzebuje między dwoma impulsami. Potem od nowa.`,l1vybm:`Stop
LED włączona · pisk`,ywa890:`Stop, LED włączona, krótki pisk`,"17krb65":`Zablokowane albo utknięte: silniki stają, LED się zapala, a brzęczyk piszczy przez {beepMs} ms.`,"1njcbjw":`Utknął?`,"6b9vj0":`Utknął na czymś, czego wiązka nie zauważyła?`,"12aymoo":`Wiązka czujnika ma tylko około 15° szerokości, więc auto może zahaczyć o róg, którego nigdy nie widziało. Jeśli odczyt nie zmienił się o więcej niż {changeCm} cm przez {stuckMsS}, choć droga wyglądała na wolną, auto utknęło. (Brak echa, 400, nigdy się nie liczy: wolna przestrzeń to nie „utknięcie”.)`,"7k6lib":`Wycofaj się`,ooiwv8:`Wycofuje się przez {backOffMsS} od tego, co je trzyma, i dopiero wtedy się rozgląda.`,"1d4sv1w":`Spójrz w prawo, potem w lewo`,"18crqcc":`Głowica obraca się na {lookRight}° (w prawo) i na {lookLeft}° (w lewo). Za każdym razem serwo dostaje {settleMsS}, by tam dojechać, zanim czujnik zostanie odczytany; oba odczyty są wypisywane.`,"1r9o4nf":`Czy jest miejsce na skręt?`,"122yr22":`Jeśli żadna strona nie ma {tightCm} cm (TIGHT_CM), nie ma tu miejsca na skręt.`,"1i7u6tc":`Cofnij się, spójrz ponownie`,"1ik4v71":`Cofnij się i spójrz ponownie`,a0a741:`Zamknięte w pułapce: cofa się przez {backMsS} i stamtąd znów patrzy w prawo i w lewo, tyle razy, ile trzeba.`,"1yfjvg4":`Właśnie skręcił?`,"2jbjim":`Znowu zablokowany zaraz po skręcie?`,"3dv25u":`Głowica wraca na środek. Potem: jeśli ostatni skręt skończył się mniej niż {againMsS} temu, auto prawie się nie ruszyło od skrętu.`,"1steplx":`Znów w tę samą stronę`,kn4k3y:`Skręć znów w tę samą stronę`,"1k7wpmb":`Skręt w drugą stronę zaprowadziłby je tylko tam, gdzie było: w rogu skręcałoby w lewo, w prawo, w lewo bez końca. Więc skręca dalej w tę stronę, w którą skręciło ostatnio, bez względu na oba odczyty.`,"1lf2d81":`Strona z większą ilością miejsca`,"1u19y2l":`Skręć w stronę z większą ilością miejsca`,"1n1zre5":`W lewo, jeśli odczyt po lewej jest co najmniej tak duży jak po prawej, w przeciwnym razie w prawo.`,"5j8yhm":`Skręt`,"4h9f4g":`Obie strony pracują przeciwnie przez TURN_MS ({turnMs} ms, około ćwierć obrotu: dostosuj to do swojej podłogi). Potem auto staje, zapamiętuje, w którą stronę i kiedy skręciło, a loop() zaczyna od góry.`,mz8bk9:`Tryb Auto`,rg9t88:`Dziesięć razy na sekundę loop() wysyła impuls czujnika i zapisuje odczyt w distance (w tym samym czasie trafia on do RoboKit). W trybie Auto autoStep() decyduje potem, co z nim zrobić.`,"15ai7e9":`Zablokowane oznacza, że coś jest bliżej niż {stopCm} cm (STOP_CM). Odczyt może mieć do {sampleMsS}, więc zaraz po skręcie czeka {freshMs} ms na taki, który zmierzono już w nowym kierunku. W przeciwnym razie auto jedzie dalej.`,"1wwbbaz":`Gdy jedzie, dir ma wartość "forward": koniec loop() zamienia to na dwie prędkości silników, z prędkością ustawioną w RoboKit.`,q8ujdx:`Wiązka czujnika ma tylko około 15° szerokości, więc auto może zahaczyć o róg, którego nigdy nie widziało. Jeśli odczyt nie zmienił się o więcej niż {changeCm} cm przez {stuckMsS} podczas jazdy, auto utknęło: wycofuje się, zanim się rozejrzy. (Brak echa, 400, nigdy się nie liczy: wolna przestrzeń to nie „utknięcie”.)`,"1e83w8t":`Głowica obraca się na {lookRight}° (w prawo), potem na {lookLeft}° (w lewo). Każdy odczyt jest brany, gdy serwo miało czas tam dojechać, a głowica wraca na środek.`,"1pjappa":`Jeśli ostatni skręt skończył się mniej niż {againMsS} temu, auto prawie się nie ruszyło od skrętu. (Włączenie Auto zaczyna od nowa: turnedAt ma wtedy wartość 0.)`,pjp20w:`Skręt w drugą stronę zaprowadziłby je tylko tam, gdzie było: w rogu skręcałoby w lewo, w prawo, w lewo bez końca. Więc goLeft zostaje bez zmian, a auto skręca w tę stronę, w którą skręciło ostatnio, bez względu na oba odczyty.`,ihilws:`Obie strony pracują przeciwnie przez TURN_MS ({turnMs} ms, około ćwierć obrotu: dostosuj to do swojej podłogi). Potem LED gaśnie, czas zostaje zapisany, a auto znowu jedzie.`,"1k1y69x":`4× silnik TT`,"15bpusl":`8× uchwyt silnika`,dgwrs0:`Śruby M3, nakrętki, wkręty`,"1mkf3n0":`4× koło, 65 mm`,"19aemsl":`Sterownik L9110S`,"123jzux":`podkładka piankowa`,a4iz5j:`Płytka rozszerzeń ESP32`,"1al7iyf":`uchwyt czujnika`,a89ttz:`Serwo SG90`,"1alynuo":`orczyk`,"1pbblc6":`Koszyk 2 × 18650`,muur5i:`2× ogniwo 18650`,"1t10ooq":`włącznik`,"7h9qib":`brzęczyk aktywny`,"1uw5qdo":`wtyk DC`,"1l9u4j2":`16× tulejka dystansowa M3`,hiufn9:`przewód montażowy`,"1w4hkux":`20× przewody połączeniowe (Ż–Ż, 15 cm)`,"1onzquf":`dolna płyta`,"1h4bzq9":`środkowa płyta`,myp2cd:`górna płyta`,pu413r:`Przeglądarki blokują ws:// na stronie otwartej przez https:// — uruchom RoboKit na swoim komputerze (npm run dev), aby połączyć się z autem`,tqkecz:`Ta strona jest serwowana przez https, więc przeglądarka nie pozwoli jej otworzyć ws:// do auta. Aby sterować prawdziwym autem, uruchom RoboKit na swoim komputerze (npm install, potem npm run dev) i otwórz http://localhost:5173.`,vqmrol:`Twój komputer musi być w sieci „RoboKit”, a RoboKit musi być otwarty przez http://, a nie https://: przeglądarki blokują ws:// na bezpiecznych stronach, więc kopia hostowana w sieci nie połączy się z autem. Uruchom go na swoim komputerze (npm install, póki masz jeszcze internet, potem npm run dev) i otwórz http://localhost:5173.`};export{e as default};